<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { useQuery, useQueryClient } from '@tanstack/vue-query';
import { ArrowDownWideNarrow, ArrowRight, Clock3, Database, Files, FolderGit2, GitBranch, Globe2, HardDrive, LayoutGrid, List, LoaderCircle, LockKeyhole, Plus, Rows3, Search, Upload, X } from 'lucide-vue-next';
import type { JsonlImportResult, RepoSummary } from '@oxen/shared';
import type { CatalogFilter, DatasetCatalogField } from '../../../../packages/shared/src/catalog-types';
import {activityTime,catalogFacets,catalogKeyword,catalogStateLabel,filterCatalogRepos,matchesProjectKeywords,primaryCatalogTags,projectKeywordId,sortCatalogRepos,toggleProjectKeyword,type CatalogSort} from '../catalog';
import ImportDatasetDialog from '../components/ImportDatasetDialog.vue';
import RepositoryRecycleBin from '../components/RepositoryRecycleBin.vue';
import {withProjectKeywords} from '../project-label-chips';
import { post, request } from '../api';
import { useAppStore } from '../stores/app';
import {credentialContext,repositoryQueryKey} from '../access-context';
const app=useAppStore(), cache=useQueryClient(), router=useRouter(), route=useRoute();
const explore=computed(()=>route.name==='explore');
const canCreate=computed(()=>app.status?.identity?.kind==='owner'&&app.status?.capabilities.write===true);
const canImport=computed(()=>['owner','collaborator'].includes(app.status?.identity?.kind||'')&&app.status?.capabilities.write===true);
const {data:repos,isPending,error,refetch}=useQuery({queryKey:computed(()=>repositoryQueryKey(app.status?.identity)),queryFn:({signal})=>request<RepoSummary[]>('/repos',{signal})});
const search=ref(typeof route.query.q==='string'?route.query.q:''),searchInput=ref<HTMLInputElement|null>(null),sort=ref<CatalogSort>('updated'),layout=ref<'grid'|'list'>('grid');
const catalogFilters=ref<CatalogFilter[]>([]),catalogState=ref('all'),keywordFilters=ref<string[]>([]);
const namespaceFilter=ref(''),visibilityFilter=ref('all'),showImport=ref(false),showNew=ref(false),busy=ref(false),formError=ref('');
const form=ref({namespace:'local',name:'',description:'',visibility:'private'}),namespaceTouched=ref(false);
const identityName=computed(()=>explore.value?'公开项目':app.status?.identity?.name||'我的工作空间');
const visibleRepos=computed(()=>(repos.value??[]).filter(repo=>!explore.value||repo.visibility==='public'));
const namespaces=computed(()=>[...new Set(visibleRepos.value.map(repo=>repo.namespace))].sort());
const keywordRepos=computed(()=>visibleRepos.value.filter(repo=>(!namespaceFilter.value||repo.namespace===namespaceFilter.value)&&(visibilityFilter.value==='all'||repo.visibility===visibilityFilter.value)&&catalogKeyword(repo).includes(search.value.toLocaleLowerCase())));
const facets=computed(()=>catalogFacets(keywordRepos.value.filter(repo=>matchesProjectKeywords(repo,keywordFilters.value)),catalogFilters.value,catalogState.value));
const filtered=computed(()=>sortCatalogRepos(filterCatalogRepos(keywordRepos.value,catalogFilters.value,catalogState.value,keywordFilters.value),sort.value));
const selectedChips=computed(()=>catalogFilters.value.flatMap(filter=>{const facet=facets.value.find(item=>item.key===filter.key),label=facet?`${facet.organizationId} · ${facet.label}`:filter.key;return [...filter.values.map(id=>({key:filter.key,id,label:`${label}：${facet?.options.find(option=>option.id===id)?.label??id}`})),...(filter.unset?[{key:filter.key,id:'@unset',label:`${label}：未填写`}]:[])];}));
const totalFiles=computed(()=>visibleRepos.value.reduce((n,repo)=>n+repo.fileCount,0));
const totalSize=computed(()=>visibleRepos.value.reduce((n,repo)=>n+repo.size,0));
const hasFilters=computed(()=>!!search.value||!!namespaceFilter.value||visibilityFilter.value!=='all'||catalogFilters.value.length>0||catalogState.value!=='all'||keywordFilters.value.length>0);
watch(repos,values=>{if(!namespaceTouched.value&&values?.[0]?.namespace)form.value.namespace=values[0].namespace;},{immediate:true});
watch(()=>route.query.q,value=>{search.value=typeof value==='string'?value:'';});
watch(namespaceFilter,()=>{catalogFilters.value=[];keywordFilters.value=[];});
watch(()=>credentialContext(app.status?.identity),()=>{namespaceFilter.value='';visibilityFilter.value='all';catalogFilters.value=[];keywordFilters.value=[];catalogState.value='all';});
watch(explore,()=>{namespaceFilter.value='';visibilityFilter.value='all';catalogFilters.value=[];keywordFilters.value=[];catalogState.value='all';});
function bytes(value:number){if(!value)return '0 B';const index=Math.min(Math.floor(Math.log(value)/Math.log(1024)),3);return `${(value/1024**index).toFixed(index?1:0)} ${['B','KB','MB','GB'][index]}`;}
function relativeDate(value?:string){const time=Date.parse(value??'');if(!Number.isFinite(time))return '时间未提供';const minutes=Math.max(0,Math.floor((Date.now()-time)/60000));if(minutes<1)return '刚刚';if(minutes<60)return `${minutes} 分钟前`;if(minutes<1440)return `${Math.floor(minutes/60)} 小时前`;if(minutes<43200)return `${Math.floor(minutes/1440)} 天前`;return new Date(time).toLocaleDateString('zh-CN');}
function fullDate(value?:string){return value!==undefined&&Number.isFinite(Date.parse(value))?new Date(value).toLocaleString('zh-CN'):'时间未提供';}
function activityTitle(repo:RepoSummary){return `${fullDate(activityTime(repo))}${repo.activity?.source==='local-draft'?' · 本人本机草稿活动，尚未提交':repo.activity?.source==='created'?' · 本机记录的项目创建时间':repo.activity?.commitId?` · ${repo.activity.branch}@${repo.activity.commitId.slice(0,10)} 的实际提交`:''}${repo.activity?.state==='partial'?' · 部分分支时间暂不可用':''}`;}
function toggleFilter(key:string,id:string){const current=catalogFilters.value.find(item=>item.key===key)??{key,values:[]};const next={...current,values:[...current.values]};if(id==='@unset')next.unset=!next.unset;else next.values=next.values.includes(id)?next.values.filter(value=>value!==id):[...next.values,id];catalogFilters.value=catalogFilters.value.filter(item=>item.key!==key);if(next.values.length||next.unset)catalogFilters.value.push(next);}
function positionFacet(event:Event){const details=event.target as HTMLDetailsElement;if(!details.open)return;const menu=details.querySelector<HTMLElement>('.catalog-facet-options');if(!menu)return;const rect=details.getBoundingClientRect(),width=Math.min(290,window.innerWidth-44);menu.style.width=width+'px';menu.style.left=(Math.max(16,Math.min(rect.left,window.innerWidth-width-16))-rect.left)+'px';}
function isSelected(key:string,id:string){const filter=catalogFilters.value.find(item=>item.key===key);return id==='@unset'?!!filter?.unset:!!filter?.values.includes(id);}
function selectTag(field:DatasetCatalogField,id:string){toggleFilter(field.key,id);}
function keywordSelected(value:string){return keywordFilters.value.some(item=>projectKeywordId(item)===projectKeywordId(value));}
function selectKeyword(value:string){keywordFilters.value=toggleProjectKeyword(keywordFilters.value,value);}
function cardTags(repo:RepoSummary){return withProjectKeywords(primaryCatalogTags(repo).map(tag=>({...tag,key:tag.field.key+':'+tag.value.id,label:tag.value.label})),repo.catalog?.keywords??[]);}
function repoLink(repo:RepoSummary){return `/repos/${encodeURIComponent(repo.namespace)}/${encodeURIComponent(repo.name)}/overview`;}
function samples(repo:RepoSummary){return typeof repo.sampleCount==='number'?repo.sampleCount.toLocaleString():'—';}
function samplesTitle(repo:RepoSummary){return repo.sampleCountState==='ready'?`默认分支 ${repo.defaultBranch} · ${repo.sampleCountCommitId?.slice(0,10)||''}`:repo.sampleCountState==='not-dataset'?'此项目尚无规范数据集':'暂时无法统计样本数';}
function resetFilters(){search.value='';namespaceFilter.value='';visibilityFilter.value='all';catalogFilters.value=[];keywordFilters.value=[];catalogState.value='all';}
function openNew(){formError.value='';showNew.value=true;}
function closeNew(){if(!busy.value)showNew.value=false;}
async function create(){if(busy.value||!canCreate.value)return;busy.value=true;formError.value='';try{await post('/repos',{namespace:form.value.namespace.trim(),name:form.value.name.trim(),description:form.value.description,visibility:form.value.visibility});await cache.invalidateQueries({queryKey:['repos']});showNew.value=false;form.value.name='';form.value.description='';app.notify('项目已创建，可导入或直接添加样本。');}catch(cause){formError.value=(cause as Error).message;}finally{busy.value=false;}}
async function imported(result:JsonlImportResult){showImport.value=false;await cache.invalidateQueries({queryKey:['repos']});app.notify(`已导入 ${result.rowCount.toLocaleString()} 条样本`);await router.push({path:`/repos/${encodeURIComponent(result.namespace)}/${encodeURIComponent(result.repo)}/table`,query:{branch:result.branch}});}
function focusSearch(event:KeyboardEvent){if(event.key!=='/'||event.ctrlKey||event.metaKey||event.altKey)return;const target=event.target as HTMLElement|null;if(target?.isContentEditable||/^(INPUT|TEXTAREA|SELECT)$/.test(target?.tagName||''))return;const modalOpen=Array.from(document.querySelectorAll<HTMLElement>('[role="dialog"],[role="alertdialog"]')).some(element=>element.getClientRects().length>0&&getComputedStyle(element).visibility!=='hidden');if(!modalOpen){event.preventDefault();searchInput.value?.focus();}}
onMounted(()=>window.addEventListener('keydown',focusSearch));onBeforeUnmount(()=>window.removeEventListener('keydown',focusSearch));
</script>
<template>
<div class="page repositories-page">
  <section class="workspace-overview" aria-label="工作空间概览"><div class="workspace-identity"><span class="workspace-avatar"><Globe2 v-if="explore" :size="25"/><span v-else>{{identityName.slice(0,2).toUpperCase()}}</span></span><div><span class="eyebrow">{{explore?'DISCOVER':'WORKSPACE'}}</span><h1>{{identityName}}</h1><p>{{explore?'浏览公开的数据、文件与版本记录。':'在项目中组织数据，与团队一起管理每次变化。'}}</p></div></div><dl class="workspace-metrics"><div><dt><FolderGit2 :size="14"/>可访问项目</dt><dd>{{isPending?'—':visibleRepos.length.toLocaleString()}}</dd></div><div><dt><Files :size="14"/>版本化文件</dt><dd>{{isPending?'—':totalFiles.toLocaleString()}}</dd></div><div><dt><HardDrive :size="14"/>数据存储</dt><dd>{{isPending?'—':bytes(totalSize)}}</dd></div></dl></section>
  <section class="projects-section" aria-labelledby="projects-heading">
    <header class="projects-heading"><div><h2 id="projects-heading">{{explore?'公开项目':'项目'}}</h2><span class="project-count">{{visibleRepos.length}}</span></div><div v-if="!explore" class="project-actions"><button class="btn" :disabled="!canImport" @click="showImport=true"><Upload :size="16"/>导入数据集</button><button class="btn btn-primary" :disabled="!canCreate" @click="openNew"><Plus :size="17"/>新建项目</button></div></header>
    <div class="projects-toolbar"><label class="search-field project-search"><Search :size="17"/><input ref="searchInput" v-model="search" aria-label="搜索仓库" placeholder="搜索项目、描述或标签"/><button v-if="search" class="search-clear" aria-label="清空项目搜索" @click="search=''"><X :size="14"/></button><kbd v-else>/</kbd></label><div class="project-filters"><label v-if="namespaces.length>1" class="project-select"><span class="sr-only">命名空间</span><select v-model="namespaceFilter" aria-label="筛选命名空间"><option value="">全部命名空间</option><option v-for="name in namespaces" :key="name">{{name}}</option></select></label><label v-if="!explore" class="project-select"><span class="sr-only">访问范围</span><select v-model="visibilityFilter" aria-label="筛选项目访问范围"><option value="all">全部访问范围</option><option value="private">私有项目</option><option value="public">公开项目</option></select></label><label class="project-select project-sort"><ArrowDownWideNarrow :size="15"/><select v-model="sort" aria-label="仓库排序"><option value="updated">最近修改 · 倒序</option><option value="created">最近添加 · 倒序</option><option value="name">项目名称</option><option value="size">存储大小</option></select></label><div class="project-view-toggle" role="group" aria-label="项目视图"><button :class="{selected:layout==='grid'}" :aria-pressed="layout==='grid'" aria-label="卡片视图" @click="layout='grid'"><LayoutGrid :size="17"/></button><button :class="{selected:layout==='list'}" :aria-pressed="layout==='list'" aria-label="列表视图" @click="layout='list'"><List :size="18"/></button></div></div></div>
    <section v-if="!isPending&&!error" class="catalog-filter-bar" aria-label="项目标签筛选"><div class="catalog-filter-heading"><span>项目标签</span><p>同维度任一值，跨维度同时满足；关键词同时包含，并与搜索一起筛选</p></div><div class="catalog-facets"><details v-for="facet in facets" :key="facet.key" class="catalog-facet" @toggle="positionFacet"><summary>{{facet.label}}<small v-if="namespaces.length>1">{{facet.organizationId}}</small><b v-if="catalogFilters.find(item=>item.key===facet.key)">{{(catalogFilters.find(item=>item.key===facet.key)?.values.length??0)+(catalogFilters.find(item=>item.key===facet.key)?.unset?1:0)}}</b></summary><div class="catalog-facet-options"><strong>{{facet.organizationId}} · {{facet.label}}</strong><label v-for="option in facet.options" :key="option.id"><input type="checkbox" :checked="isSelected(facet.key,option.id)" @change="toggleFilter(facet.key,option.id)"/><span>{{option.label}}<em v-if="option.deprecated">已弃用</em></span><small>{{option.count}}</small></label><label v-if="facet.role!=='domain'"><input type="checkbox" :checked="isSelected(facet.key,'@unset')" @change="toggleFilter(facet.key,'@unset')"/><span>未填写</span><small>{{facet.unsetCount}}</small></label></div></details><label class="project-select catalog-state"><select v-model="catalogState" aria-label="项目标签状态"><option value="all">全部标签状态</option><option value="unassigned">尚未填写</option><option value="unconfigured">未配置项目标签模板</option><option value="conflicted">标签有分歧</option><option value="unavailable">暂不可用</option></select></label><p v-if="!facets.length" class="catalog-facet-empty">当前范围尚无已配置的项目标签。</p></div><div v-if="selectedChips.length||catalogState!=='all'||keywordFilters.length" class="catalog-selected"><button v-for="keyword in keywordFilters" :key="'keyword:'+keyword" class="catalog-keyword-filter" :aria-label="'移除关键词筛选：'+keyword" @click="selectKeyword(keyword)">关键词：{{keyword}}<X :size="12"/></button><button v-for="chip in selectedChips" :key="chip.key+chip.id" @click="toggleFilter(chip.key,chip.id)">{{chip.label}}<X :size="12"/></button><button v-if="catalogState!=='all'" @click="catalogState='all'">状态：{{({unassigned:'尚未填写',unconfigured:'未采用模板',conflicted:'有分歧',unavailable:'暂不可用'} as Record<string,string>)[catalogState]}}<X :size="12"/></button></div></section>
    <div v-if="hasFilters&&!isPending" class="filter-summary"><span>{{filtered.length.toLocaleString()}} 个匹配项目</span><button @click="resetFilters">清除筛选<X :size="12"/></button></div>
    <div v-if="isPending" class="projects-grid" aria-label="正在加载项目" aria-busy="true"><div v-for="index in 6" :key="index" class="project-skeleton"><span></span><span></span><div></div><span></span></div></div>
    <div v-else-if="error" class="error-state" role="alert"><span>无法加载项目：{{(error as Error).message}}</span><button class="btn" @click="refetch()">重新加载</button></div>
    <section v-else-if="!filtered.length" class="projects-empty"><span class="empty-project-icon"><FolderGit2 :size="29" :stroke-width="1.5"/></span><h3>{{hasFilters?'没有匹配的项目':explore?'暂无公开项目':'创建第一个项目'}}</h3><p>{{hasFilters?'调整名称、命名空间或访问范围，查找需要的项目。':explore?'获得公开访问权限的项目会出现在这里。':'将数据放入项目，开始浏览、整理并与团队协作。'}}</p><button v-if="hasFilters" class="btn" @click="resetFilters">清除筛选</button><button v-else-if="!explore&&canCreate" class="btn btn-primary" @click="openNew"><Plus :size="16"/>新建项目</button></section>
    <div v-else-if="layout==='grid'" class="projects-grid"><article v-for="repo in filtered" :key="repo.namespace+'/'+repo.name" class="project-card"><header><span class="project-folder"><FolderGit2 :size="20" :stroke-width="1.6"/></span><span class="project-namespace">{{repo.namespace}}</span><span class="project-visibility"><LockKeyhole v-if="repo.visibility==='private'" :size="11"/><Globe2 v-else-if="repo.visibility==='public'" :size="11"/>{{repo.visibility==='private'?'私有':repo.visibility==='public'?'公开':'本地'}}</span></header><RouterLink :to="repoLink(repo)" class="project-title">{{repo.displayName||repo.name}}</RouterLink><p class="project-description">{{repo.description||'此项目尚未填写描述。'}}</p><div class="project-tags catalog-card-tags"><template v-for="tag in cardTags(repo).slice(0,3)" :key="tag.key"><button v-if="tag.kind==='structured'" :aria-pressed="isSelected(tag.field.key,tag.value.id)" :title="tag.field.name+'：'+tag.label" @click="selectTag(tag.field,tag.value.id)">{{tag.label}}</button><button v-else class="project-keyword" :aria-pressed="keywordSelected(tag.label)" :title="'筛选项目关键词：'+tag.label" @click="selectKeyword(tag.label)">{{tag.label}}</button></template><span v-if="!cardTags(repo).length" class="catalog-state-label" :class="repo.catalog?.state">{{catalogStateLabel(repo)}}</span><details class="catalog-card-details"><summary>{{cardTags(repo).length>3?'+'+(cardTags(repo).length-3):'详情'}}</summary><div><strong>项目标签 · main <code>{{repo.catalog?.commitId?.slice(0,10)??'版本未知'}}</code></strong><p>{{catalogStateLabel(repo)}}</p><dl v-for="field in repo.catalog?.fields??[]" :key="field.key"><dt>{{field.name}}</dt><dd><span v-if="field.conflicted">存在分歧，等待裁决</span><span v-else-if="!field.values.length">尚未填写</span><span v-else-if="field.type==='text'">{{field.values.map(value=>value.label).join('、')}}</span><button v-else v-for="option in field.values" :key="option.id" :aria-pressed="isSelected(field.key,option.id)" @click="selectTag(field,option.id)">{{option.label}}</button></dd></dl><p v-if="repo.catalog?.templates.dataset">项目标签模板：{{repo.catalog.templates.dataset.name}} v{{repo.catalog.templates.dataset.version}}{{repo.catalog.templates.dataset.legacy?' · 兼容规范':''}}</p><div v-if="repo.catalog?.keywords?.length" class="catalog-extra-keywords"><span>项目关键词</span><button v-for="keyword in repo.catalog.keywords" :key="keyword" :aria-pressed="keywordSelected(keyword)" @click="selectKeyword(keyword)">{{keyword}}</button></div><p v-for="warning in repo.catalog?.warnings??[]" :key="warning">{{warning}}</p></div></details></div><dl class="project-stats"><div><dt><Clock3 :size="13"/>修改</dt><dd :title="activityTitle(repo)">{{relativeDate(activityTime(repo))}}<small v-if="repo.activity?.source==='local-draft'" class="draft-activity">本机草稿</small></dd></div><div><dt><Files :size="13"/>文件</dt><dd>{{repo.fileCount.toLocaleString()}}</dd></div><div><dt><Rows3 :size="13"/>样本数</dt><dd :title="samplesTitle(repo)">{{samples(repo)}}</dd></div><div><dt><HardDrive :size="13"/>总大小</dt><dd>{{bytes(repo.size)}}</dd></div></dl><p class="project-added" :title="fullDate(repo.activity?.createdAt??repo.createdAt)">添加于 {{relativeDate(repo.activity?.createdAt??repo.createdAt)}}</p><footer><span class="project-branch"><GitBranch :size="13"/>{{repo.defaultBranch||'—'}}</span><RouterLink :to="repoLink(repo)" class="project-open">查看项目<ArrowRight :size="15"/></RouterLink></footer></article></div>
    <div v-else class="projects-table-wrap"><table class="projects-table"><thead><tr><th>项目</th><th>最近修改 / 添加</th><th>文件</th><th>样本数</th><th>总大小</th><th>默认分支</th><th><span class="sr-only">打开项目</span></th></tr></thead><tbody><tr v-for="repo in filtered" :key="repo.namespace+'/'+repo.name"><td><div class="project-list-name"><FolderGit2 :size="18"/><div><RouterLink :to="repoLink(repo)">{{repo.displayName||repo.name}}</RouterLink><span>{{repo.namespace}}<b>·</b>{{repo.visibility==='private'?'私有':repo.visibility==='public'?'公开':'本地'}}</span><div class="catalog-list-tags"><template v-for="tag in cardTags(repo).slice(0,3)" :key="tag.key"><button v-if="tag.kind==='structured'" :aria-pressed="isSelected(tag.field.key,tag.value.id)" @click="selectTag(tag.field,tag.value.id)">{{tag.label}}</button><button v-else class="project-keyword" :aria-pressed="keywordSelected(tag.label)" :title="'筛选项目关键词：'+tag.label" @click="selectKeyword(tag.label)">{{tag.label}}</button></template><small v-if="cardTags(repo).length>3">+{{cardTags(repo).length-3}}</small><small v-if="!cardTags(repo).length">{{catalogStateLabel(repo)}}</small></div></div></div></td><td :title="activityTitle(repo)"><span>{{relativeDate(activityTime(repo))}}</span><small class="project-list-added">添加 {{relativeDate(repo.activity?.createdAt??repo.createdAt)}}</small><small v-if="repo.activity?.source==='local-draft'" class="draft-activity">本机草稿，未提交</small></td><td>{{repo.fileCount.toLocaleString()}}</td><td class="mono" :title="samplesTitle(repo)">{{samples(repo)}}</td><td class="mono">{{bytes(repo.size)}}</td><td><span class="project-branch"><GitBranch :size="13"/>{{repo.defaultBranch||'—'}}</span></td><td><RouterLink :to="repoLink(repo)" class="list-open" :aria-label="`打开项目 ${repo.name}`"><ArrowRight :size="17"/></RouterLink></td></tr></tbody></table></div>
    <footer v-if="filtered.length&&!isPending" class="projects-footer"><span>{{filtered.length.toLocaleString()}} 个项目</span><span><span class="service-dot" :class="{online:app.status?.ready}"></span>{{app.status?.ready?'已连接 Oxen 服务':'服务未就绪'}}</span></footer>
  </section>
</div>
<RepositoryRecycleBin v-if="app.status?.authenticated&&!explore" @restored="refetch()"/>
<ImportDatasetDialog v-if="showImport" :repos="repos||[]" @close="showImport=false" @imported="imported"/>
<div v-if="showNew" class="modal-backdrop" @click.self="closeNew"><section class="modal project-create-dialog" role="dialog" aria-modal="true" aria-labelledby="new-repo" @keydown.esc="closeNew"><header class="panel-header"><div><h2 id="new-repo">新建项目</h2><p>组织数据、管理版本，并与协作者共享工作。</p></div><button class="icon-button" :disabled="busy" aria-label="关闭新建项目" @click="closeNew"><X :size="19"/></button></header><form @submit.prevent="create"><fieldset :disabled="busy"><label class="field">项目名称<input v-model="form.name" required pattern="[A-Za-z0-9][A-Za-z0-9_.-]*" maxlength="100" placeholder="my-first-project" autofocus/><small>使用英文字母、数字、点、下划线或连字符。</small></label><label class="field">命名空间<input v-model="form.namespace" @input="namespaceTouched=true" required pattern="[A-Za-z0-9][A-Za-z0-9_.-]*" maxlength="100"/></label><label class="field">描述<textarea v-model="form.description" rows="3" maxlength="2000" placeholder="这个项目用于什么？"/></label><label class="field">访问范围<select v-model="form.visibility"><option value="private">私有 · 仅获授权的成员可访问</option><option value="public">公开 · 所有人可读取</option></select></label></fieldset><p v-if="formError" class="error-state" role="alert">{{formError}}</p><footer class="modal-actions"><button type="button" class="btn" :disabled="busy" @click="closeNew">取消</button><button class="btn btn-primary" :disabled="busy||!canCreate"><LoaderCircle v-if="busy" class="spin" :size="15"/>{{busy?'正在创建…':'创建项目'}}</button></footer></form></section></div>
</template>
<style scoped src="./RepositoriesView.css"/>
